import{_ as a,o as r,c as n,a2 as t}from"./chunks/framework.om2R87yU.js";const c=JSON.parse('{"title":"Migration to newer versions","description":"Tips and hints on how to migrate your current BullMQ version to a newer one.","frontmatter":{"description":"Tips and hints on how to migrate your current BullMQ version to a newer one."},"headers":[],"relativePath":"guide/migrations/migration-to-newer-versions.md","filePath":"guide/migrations/migration-to-newer-versions.md","lastUpdated":1757277711000}'),i={name:"guide/migrations/migration-to-newer-versions.md"};function s(o,e,u,l,g,d){return r(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="migration-to-newer-versions" tabindex="-1">Migration to newer versions <a class="header-anchor" href="#migration-to-newer-versions" aria-label="Permalink to &quot;Migration to newer versions&quot;">​</a></h1><p>BullMQ&#39;s team regularly releases new versions packed with bug fixes, new features, or occasionally, breaking changes. As a user operating in a production environment, you might find upgrading to these new versions while maintaining service continuity challenging. This guide offers tips and advice to ease your transition.</p><p>The strategies needed vary depending on the nature of the upgrade. Regardless, we urge you to read this guide thoroughly, irrespective of the upgrade you&#39;re pursuing.</p><h2 id="general-advice" tabindex="-1">General advice <a class="header-anchor" href="#general-advice" aria-label="Permalink to &quot;General advice&quot;">​</a></h2><p>When upgrading BullMQ, always consult the <em>Changelog</em>. It helps determine the extent of the changes and flags crucial considerations before upgrading.</p><p>Avoid making large leaps between versions. If you&#39;re currently on version 1.3.7, for instance, a jump to version 4.2.6 may not be advisable. Upgrade incrementally whenever possible. Start with as many bugfix releases as possible, then proceed to new features, and finally, the major releases that encompass breaking changes.</p><h2 id="bugfix-upgrade" tabindex="-1">Bugfix upgrade <a class="header-anchor" href="#bugfix-upgrade" aria-label="Permalink to &quot;Bugfix upgrade&quot;">​</a></h2><p>Bugfix releases increase only the micro version number according to <a href="https://semver.org/" target="_blank" rel="noreferrer">SemVer (<em>Semantic Versioning</em>)</a> (for instance, an upgrade from 3.14.4 to 3.14.7). Bugfix upgrades require no special strategies; simply update your instances to the latest version without changing your code or deployment. While it&#39;s not critical that all instances run on the same version, we recommend it for consistency.</p><h2 id="new-feature-upgrade" tabindex="-1">New feature upgrade <a class="header-anchor" href="#new-feature-upgrade" aria-label="Permalink to &quot;New feature upgrade&quot;">​</a></h2><p>Following the SemVer specification, new features result in an increase in the minor version number (like going from 3.14.7 to 3.20.5). Generally, you can treat feature upgrades like bugfix upgrades — update all your instances to the latest version.</p><p>However, if you&#39;re also upgrading your code to utilize a new feature, ensure it&#39;s backward compatible with the older BullMQ version. Otherwise, an older <code>Worker</code> might stop functioning if a new <code>Queue</code> adds jobs leveraging a feature the older <code>Worker</code> doesn&#39;t understand.</p><p>The strategy here is to first upgrade all your instances to the version featuring the new functionality. After confirming all instances run the new version, proceed to deploy your code depending on those new features.</p><h2 id="breaking-changes" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h2><p>Occasionally, unavoidable changes incompatible with previous versions are made. We strive to minimize these, classifying them into two types: API-breaking changes and data structure-breaking changes.</p><h3 id="api-breaking-changes" tabindex="-1">API breaking changes <a class="header-anchor" href="#api-breaking-changes" aria-label="Permalink to &quot;API breaking changes&quot;">​</a></h3><p>API breaking changes could involve altered method parameters, removals, or different operational methods. These changes are usually straightforward to apply — you can run your BullMQ-dependent unit tests and address issues based on these changes. If you&#39;re using TypeScript, compilation errors will likely surface. Always read the <a href="./../changelog">changelog</a> for essential information about these changes.</p><h3 id="data-structure-breaking-changes" tabindex="-1">Data structure breaking changes <a class="header-anchor" href="#data-structure-breaking-changes" aria-label="Permalink to &quot;Data structure breaking changes&quot;">​</a></h3><p>Data structure changes, which alter the queue&#39;s underlying structure, are more challenging. They can be either</p><ul><li><strong>additive</strong> (introducing new data structures that older BullMQ versions don&#39;t understand), or</li><li><strong>destructive</strong> (changing or eradicating older data structures).</li></ul><p>For additive changes, you could simply upgrade all instances to the new version — they should apply the change and continue working without issues, akin to a <a href="./migration-to-newer-versions#new-features-upgrade">new feature upgrade</a>.</p><p>Destructive changes are the most demanding, as these fundamental alterations may make older versions unworkable, making rollback impossible if the upgrade fails. The <a href="./../changelog">changelog</a> will provide crucial information to guide you through this type of upgrade.</p><h2 id="some-general-strategies" tabindex="-1">Some general strategies <a class="header-anchor" href="#some-general-strategies" aria-label="Permalink to &quot;Some general strategies&quot;">​</a></h2><p>For the most demanding upgrades, you might find these strategies useful:</p><h3 id="pause-upgrade-unpause" tabindex="-1">Pause/Upgrade/Unpause <a class="header-anchor" href="#pause-upgrade-unpause" aria-label="Permalink to &quot;Pause/Upgrade/Unpause&quot;">​</a></h3><p>Since BullMQ supports global pause, one possible strategy, if suitable for your business case, is to pause the queue(s), wait until all current queued jobs have been processed, then perform the upgrade. Once all instances running BullMQ have been upgraded, you can unpause and let new jobs be processed by the new workers. Be aware this strategy is less useful if breaking changes affect <code>Queue</code> instances. Always consult the changelog for this type of information.</p><h3 id="use-new-queues-altogether" tabindex="-1">Use new queues altogether <a class="header-anchor" href="#use-new-queues-altogether" aria-label="Permalink to &quot;Use new queues altogether&quot;">​</a></h3><p>This drastic solution involves discontinuing use of older queues and creating new ones. You could rename older queues (e.g., &quot;myQueueV2&quot;), use a new Redis host, or maintain two versions of the service—one running an older BullMQ version with old queues, and a newer one with the latest BullMQ and a different set of queues. When the older version has no more jobs to process, it can be retired, leaving only the upgraded version.</p>',27)])])}const p=a(i,[["render",s]]);export{c as __pageData,p as default};
